INSERT INTO public.exam_config (class, is_open, total_questions, time_limit_minutes, passing_score, max_attempts, show_results_to_students)
INSERT INTO public.questions (class, subject_tag, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option)
VALUES
  (6, 'Keyboard Shortcuts', 'easy', 'Which keyboard shortcut is used to COPY selected text or a file?', 'Ctrl + X', 'Ctrl + P', 'Ctrl + C', 'Ctrl + V', 'c'),
  (6, 'Keyboard Shortcuts', 'easy', 'After copying a sentence, which shortcut do you press to PASTE it?', 'Ctrl + A', 'Ctrl + Z', 'Ctrl + V', 'Ctrl + S', 'c'),
  (6, 'Keyboard Shortcuts', 'easy', 'Which key on the keyboard lets you type ALL CAPITAL LETTERS continuously when turned on?', 'Tab', 'Caps Lock', 'Esc', 'Shift', 'b'),
  (6, 'Keyboard Shortcuts', 'easy', 'If you accidentally delete a word while typing, which shortcut immediately UNDOES your mistake?', 'Ctrl + D', 'Ctrl + U', 'Ctrl + Z', 'Ctrl + B', 'c'),
  (6, 'Keyboard Shortcuts', 'easy', 'Which shortcut quickly SAVES the document or drawing you are working on?', 'Ctrl + P', 'Ctrl + O', 'Ctrl + S', 'Ctrl + N', 'c'),
  (6, 'Keyboard Shortcuts', 'easy', 'Which key moves your typing cursor to the NEXT LINE when writing a paragraph?', 'Spacebar', 'Backspace', 'Ctrl', 'Enter', 'd'),
  (6, 'Keyboard Shortcuts', 'easy', 'Which longest key on the bottom row of a keyboard adds a blank space between words?', 'Shift key', 'Enter key', 'Spacebar', 'Alt key', 'c'),
  (6, 'Keyboard Shortcuts', 'medium', 'Which shortcut selects EVERYTHING on the page or inside a folder at once?', 'Ctrl + A', 'Ctrl + E', 'Ctrl + L', 'Ctrl + S', 'a'),
  (6, 'Keyboard Shortcuts', 'medium', 'Which shortcut CUTS (moves) selected text so you can paste it somewhere else?', 'Ctrl + K', 'Ctrl + M', 'Ctrl + C', 'Ctrl + X', 'd'),
  (6, 'Keyboard Shortcuts', 'medium', 'While watching a video on YouTube or VLC, pressing the Spacebar usually does what?', 'Prints the screen', 'Shuts down the computer', 'Pauses or plays the video', 'Deletes the video', 'c'),
  (6, 'Keyboard Shortcuts', 'medium', 'Which shortcut opens the PRINT box to print a page or save it as a PDF?', 'Ctrl + R', 'Ctrl + F', 'Ctrl + I', 'Ctrl + P', 'd'),
  (6, 'Keyboard Shortcuts', 'medium', 'In Word or Google Docs, what does pressing Ctrl + B do to selected text?', 'Deletes the text', 'Makes the text Bold (thicker)', 'Turns the text Blue', 'Moves text to the bottom', 'b'),
  (6, 'Keyboard Shortcuts', 'medium', 'In a document editor, which shortcut makes selected text Italic (slanted)?', 'Ctrl + T', 'Ctrl + I', 'Ctrl + U', 'Ctrl + L', 'b'),
  (6, 'Keyboard Shortcuts', 'medium', 'In a document editor, which shortcut UNDERLINES the selected words?', 'Ctrl + N', 'Ctrl + D', 'Ctrl + O', 'Ctrl + U', 'd'),
  (6, 'Keyboard Shortcuts', 'hard', 'What is the difference between the Backspace key and the Delete key while typing?', 'Both do the exact same thing', 'Backspace erases to the left of the cursor; Delete erases to the right of the cursor', 'Delete only works on images', 'Backspace closes the program', 'b'),
  (6, 'Keyboard Shortcuts', 'hard', 'If you want to quickly FIND a specific word on a long webpage or PDF, which shortcut do you press?', 'Ctrl + G', 'Ctrl + F', 'Ctrl + Q', 'Ctrl + H', 'b'),
  (6, 'Keyboard Shortcuts', 'hard', 'Which key at the top-left of the keyboard is commonly pressed to cancel a pop-up or exit full-screen video?', 'Insert', 'Num Lock', 'Tab', 'Esc (Escape)', 'd'),
  (6, 'Keyboard Shortcuts', 'hard', 'Which function key is the classic shortcut to REFRESH or reload a webpage in a browser?', 'F12', 'F5', 'F2', 'F1', 'b'),
  (6, 'Computer Hardware', 'easy', 'Which part of a computer looks like a TV screen and shows pictures, videos, and text?', 'Speaker', 'Mouse', 'Monitor', 'Keyboard', 'c'),
  (6, 'Computer Hardware', 'easy', 'Which hand-held device moves the pointer/arrow across the computer screen?', 'Mouse', 'Speaker', 'Scanner', 'Printer', 'a'),
  (6, 'Computer Hardware', 'easy', 'Which part of the computer is often called the "brain" because it carries out instructions?', 'Monitor Stand', 'CPU (Processor)', 'Mouse Pad', 'Headphones', 'b'),
  (6, 'Computer Hardware', 'easy', 'Which device lets you hear music, voice calls, or video sound privately without disturbing others in the lab?', 'Keyboard', 'Headphones / Earphones', 'Webcam', 'Scanner', 'b'),
  (6, 'Computer Hardware', 'easy', 'What is the small wheel between the left and right buttons of a mouse used for?', 'Turning off the monitor', 'Typing numbers', 'Charging the mouse', 'Scrolling up and down long pages', 'd'),
  (6, 'Computer Hardware', 'easy', 'Which machine puts your digital document or photo onto a real sheet of paper?', 'Scanner', 'Printer', 'Microphone', 'Webcam', 'b'),
  (6, 'Computer Hardware', 'easy', 'During an online video class, which hardware captures your live face so others can see you?', 'Printer', 'Webcam (Camera)', 'Pendrive', 'UPS', 'b'),
  (6, 'Computer Hardware', 'medium', 'During a voice call or recording, which part captures your voice into the computer?', 'Monitor', 'Projector', 'Speaker', 'Microphone (Mic)', 'd'),
  (6, 'Computer Hardware', 'medium', 'Which pocket-sized device plugs into a USB port to carry files between home and school?', 'Cooling Fan', 'UPS Battery', 'Mouse Pad', 'USB Pendrive (Flash Drive)', 'd'),
  (6, 'Computer Hardware', 'medium', 'On a laptop, what is the flat touch-sensitive rectangle below the keyboard that works like a mouse?', 'Hard Disk', 'Speaker Grill', 'Motherboard', 'Touchpad (Trackpad)', 'd'),
  (6, 'Computer Hardware', 'medium', 'Pressing the RIGHT button on a computer mouse usually opens what?', 'Computer shutdown screen', 'A small shortcut/context menu with helpful options', 'The DVD tray', 'Nothing at all', 'b'),
  (6, 'Computer Hardware', 'medium', 'Which classroom device shines your computer screen onto a large white wall or board so the whole class can watch?', 'RAM stick', 'Projector', 'Scanner', 'Router', 'b'),
  (6, 'Computer Hardware', 'medium', 'On a smartphone or tablet, the screen both shows pictures AND senses your finger taps. What is it called?', 'Touchscreen', 'Joystick', 'Barcode Reader', 'Plotter', 'a'),
  (6, 'Computer Hardware', 'medium', 'What Does "Hardware" mean in simple everyday words?', 'Only paid mobile games', 'The physical parts of a computer that you can actually see and touch', 'Websites on the internet', 'Secret passwords', 'b'),
  (6, 'Computer Hardware', 'hard', 'In Indian homes and school labs, a small box called a UPS is connected to desktop PCs. Why is it useful?', 'It provides short battery backup during a power cut so you can save your work safely', 'It makes games run faster', 'It cleans computer viruses', 'It prints color photos', 'a'),
  (6, 'Computer Hardware', 'hard', 'What is the opposite of a Printer — a device that turns a paper certificate or drawing into a digital image file on your PC?', 'Projector', 'Modem', 'Speaker', 'Scanner', 'd'),
  (6, 'Computer Hardware', 'hard', 'Which single modern cable carries BOTH sharp high-definition video AND audio from a laptop to a TV or projector?', 'Earphone jack', 'Mouse wire', 'Power cord', 'HDMI cable', 'd'),
  (6, 'Computer Hardware', 'hard', 'At a supermarket checkout or school library, which handheld device reads black-and-white striped labels instantly?', 'Microphone', 'Joystick', 'Cooling Pad', 'Barcode Scanner', 'd'),
  (6, 'Application Software & OS', 'easy', 'Where do deleted files usually go FIRST on a Windows computer so you can recover them if needed?', 'Recycle Bin', 'Control Panel', 'Calculator', 'Start Menu', 'a'),
  (6, 'Application Software & OS', 'easy', 'Which simple built-in Windows app is used for freehand drawing and coloring with a mouse?', 'Clock', 'MS Paint', 'Calculator', 'Calendar', 'b'),
  (6, 'Application Software & OS', 'easy', 'If you want to type a neat school essay or letter with headings and bullet points, which application is best?', 'Sound Recorder', 'Calculator', 'Microsoft Word or Google Docs', 'VLC Media Player', 'c'),
  (6, 'Application Software & OS', 'easy', 'To keep your school subjects organized on a computer, you put related files inside a yellow icon called a:', 'Folder', 'Wallpaper', 'Screen Saver', 'Battery', 'a'),
  (6, 'Application Software & OS', 'easy', 'Which application is best for making visual slideshows to present a project in front of your class?', 'PowerPoint or Google Slides', 'Notepad', 'Recycle Bin', 'Alarm Clock', 'a'),
  (6, 'Application Software & OS', 'easy', 'What do we call the main welcome screen with icons and wallpaper that appears after logging in to a PC?', 'BIOS', 'Desktop', 'Inbox', 'Spreadsheet', 'b'),
  (6, 'Application Software & OS', 'easy', 'Which popular free media player with an orange traffic-cone icon plays almost any video or audio file?', 'Notepad', 'Sticky Notes', 'VLC Media Player', 'MS Paint', 'c'),
  (6, 'Application Software & OS', 'medium', 'On an Android smartphone, which official app store is used to safely install apps?', 'Paint 3D', 'File Explorer', 'Recycle Bin', 'Google Play Store', 'd'),
  (6, 'Application Software & OS', 'medium', 'Look at the file name "annual_day_photo.jpg". What kind of file is it?', 'A music song only', 'A spreadsheet table', 'A computer virus', 'A picture / image file', 'd'),
  (6, 'Application Software & OS', 'medium', 'Look at the file name "school_anthem.mp3". What kind of file is it?', 'A folder', 'An audio / music file', 'A printable PDF circular', 'A website browser', 'b'),
  (6, 'Application Software & OS', 'medium', 'Look at the file name "science_fair_demo.mp4". What kind of file is it?', 'A font style', 'A plain text note', 'A video file', 'An empty folder', 'c'),
  (6, 'Application Software & OS', 'medium', 'What are the three small buttons ( — , □ , ✕ ) at the top-right corner of almost every Windows app window for?', 'Minimize, Maximize, and Close the window', 'Mute, Play, and Pause music', 'Print, Save, and Delete', 'Copy, Cut, and Paste text', 'a'),
  (6, 'Application Software & OS', 'medium', 'Which popular design app/website lets students easily create posters, certificates, and invitations using ready templates?', 'Canva', 'Command Prompt', 'Disk Cleanup', 'Device Manager', 'a'),
  (6, 'Application Software & OS', 'medium', 'What does "Software" mean in simple everyday language?', 'The apps, programs, and operating system that run inside a computer or phone', 'Soft cloth used to clean a monitor', 'The power socket on the wall', 'The plastic keyboard keys', 'a'),
  (6, 'Application Software & OS', 'hard', 'Which of the following is an Operating System (the core system software that runs a PC or phone)?', 'Canva', 'WhatsApp', 'Windows 11 / Android', 'YouTube', 'c'),
  (6, 'Application Software & OS', 'hard', 'Why do schools send circulars and admit cards as a ".pdf" file instead of an editable Word file?', 'PDFs do not take even 1 byte of space', 'PDFs automatically translate into 50 languages', 'PDFs only open at night', 'PDFs keep the exact layout, fonts, and alignment looking identical on every phone and computer', 'd'),
  (6, 'Application Software & OS', 'hard', 'Which application is best suited for keeping an attendance list, marks table, or club budget with automatic totals?', 'MS Paint', 'Sound Recorder', 'Photos viewer', 'Microsoft Excel or Google Sheets', 'd'),
  (6, 'Application Software & OS', 'hard', 'What is the difference between "Copy & Paste" and "Cut & Paste" on a file?', 'Copy works only on photos', 'Copy leaves the original file in place and makes a duplicate; Cut moves the file to the new folder', 'Cut deletes the file permanently', 'There is no difference', 'b'),
  (6, 'Web Browsing & Internet', 'easy', 'Which of the following is a Web Browser used to open websites?', 'Calculator', 'Google Chrome', 'MS Paint', 'Recycle Bin', 'b'),
  (6, 'Web Browsing & Internet', 'easy', 'If you want to keep 3 websites open inside ONE browser window without opening 3 separate windows, what feature do you use?', 'Caps Lock', 'Volume slider', 'Browser Tabs (+ button at the top)', 'Recycle Bin', 'c'),
  (6, 'Web Browsing & Internet', 'easy', 'What is a Search Engine (such as Google Search, Bing, or DuckDuckGo) used for?', 'Finding websites, information, and answers on the internet using keywords', 'Charging a mobile phone', 'Printing ID cards', 'Cooling down the laptop fan', 'a'),
  (6, 'Web Browsing & Internet', 'easy', 'In a web browser, clicking the circular arrow icon (⟳) near the address bar does what?', 'Refreshes / reloads the current webpage', 'Deletes your account', 'Shuts down the PC', 'Turns off sound', 'a'),
  (6, 'Web Browsing & Internet', 'easy', 'If you find a super useful study website and want to save it inside your browser for one-click access tomorrow, you add a:', 'Screen saver', 'Bookmark (Star ★ icon)', 'Virus scan', 'Firewall', 'b'),
  (6, 'Web Browsing & Internet', 'easy', 'When your mouse pointer turns from an arrow into a little pointing HAND over colored/underlined text on a webpage, it means:', 'The computer is frozen', 'You cannot click there', 'It is a clickable link (hyperlink) to another page or file', 'Your mouse is broken', 'c'),
  (6, 'Web Browsing & Internet', 'easy', 'Where do files you download from Chrome or Edge normally get saved on your computer by default?', 'The Clock app', 'The Fonts folder', 'The Recycle Bin', 'The "Downloads" folder', 'd'),
  (6, 'Web Browsing & Internet', 'medium', 'In an email app like Gmail, what does the small PAPERCLIP (📎) button let you do?', 'Delete your email account', 'Change your password', 'Log out immediately', 'Attach a file, photo, or PDF to send along with your email', 'd'),
  (6, 'Web Browsing & Internet', 'medium', 'What is the website address typed at the top of a browser (like `https://mapleskhatauli.com`) commonly called?', 'RAM address', 'URL (Website Address)', 'PIN code', 'Battery level', 'b'),
  (6, 'Web Browsing & Internet', 'medium', 'What does the Left Arrow (←) "Back" button at the top-left of a browser do?', 'Closes Windows', 'Erases a typed letter', 'Takes you back to the previous webpage you were just viewing', 'Rewinds YouTube by 1 hour', 'c'),
  (6, 'Web Browsing & Internet', 'medium', 'Look at an email address: `student@mapleskhatauli.com`. Which symbol always separates the username from the domain name?', '@ (At symbol)', '$ (Dollar)', '& (And)', '# (Hash)', 'a'),
  (6, 'Web Browsing & Internet', 'medium', 'What is that square black-and-white patterned box on posters or ID cards that opens a link when scanned with a phone camera?', 'QR Code', 'CPU Chip', 'SIM Card', 'Emoji', 'a'),
  (6, 'Web Browsing & Internet', 'medium', 'Which of these is ALSO a popular web browser besides Google Chrome?', 'MS Excel', 'Mozilla Firefox / Microsoft Edge / Apple Safari', 'Adobe Photoshop', 'Windows Calculator', 'b'),
  (6, 'Web Browsing & Internet', 'medium', 'If you visited a helpful website yesterday and forgot its name, which browser list helps you find it again?', 'Printer Queue', 'Bluetooth Devices', 'Browsing History (Ctrl + H)', 'Calculator History', 'c'),
  (6, 'Web Browsing & Internet', 'hard', 'What is the real difference between Google Chrome and Google Search?', 'There is zero difference', 'Both are hardware parts', 'Chrome is a search website; Google is a laptop brand', 'Chrome is the Browser app installed on your device; Google Search is a website used inside a browser to look up info', 'd'),
  (6, 'Web Browsing & Internet', 'hard', 'When you see `https://` and a padlock icon in the browser address bar before logging in, what does the "s" in `https` mean?', 'Slow connection', 'School-only website', 'Screen capture enabled', 'Secure — data between your browser and the website is encrypted so others on Wi-Fi cannot read your password', 'd'),
  (6, 'Web Browsing & Internet', 'hard', 'What does opening an "Incognito" or "Private" browser window ACTUALLY do on a shared computer?', 'It gives free unlimited mobile data', 'It stops the browser from saving your browsing history, cookies, and login session on THAT computer after you close the window', 'It makes you completely invisible to websites and your internet provider', 'It blocks all computer viruses automatically', 'b'),
  (6, 'Web Browsing & Internet', 'hard', 'If a webpage shows "404 — Page Not Found", what does that simply mean?', 'Your laptop battery is at 4%', 'Your monitor is broken', 'The specific link or page was moved, deleted, or typed with a spelling mistake', '404 people are viewing the site', 'c'),
  (6, 'Basic Networking & Connectivity', 'easy', 'Which wireless feature lets your phone or laptop connect to a home or school router without plugging in any wire?', 'Caps Lock', 'MS Paint', 'Wi-Fi', 'Recycle Bin', 'c'),
  (6, 'Basic Networking & Connectivity', 'easy', 'Which short-range wireless feature is commonly used to connect wireless earbuds, speakers, or a wireless mouse?', 'Bluetooth', 'Scanner', 'Notepad', 'HDMI', 'a'),
  (6, 'Basic Networking & Connectivity', 'easy', 'If there is no Wi-Fi nearby and you share your mobile phone’s internet with your laptop, what phone feature do you turn ON?', 'Mobile Hotspot', 'Calculator', 'Alarm Clock', 'Voice Recorder', 'a'),
  (6, 'Basic Networking & Connectivity', 'easy', 'What happens when you turn ON "Airplane Mode" on a smartphone or laptop?', 'It makes the phone fly', 'It turns off wireless radios like cellular network, Wi-Fi, and Bluetooth', 'It prints boarding passes', 'It deletes all photos', 'b'),
  (6, 'Basic Networking & Connectivity', 'easy', 'What is the box with blinking lights at home or school that shares Wi-Fi internet with phones and computers?', 'Webcam', 'Pendrive', 'Wi-Fi Router', 'Inkjet Printer', 'c'),
  (6, 'Basic Networking & Connectivity', 'easy', 'In a school computer lab, many desktop PCs are plugged into internet wall sockets using a sturdy cable with a clip plug. What is that cable called?', 'Shoe Lace', 'HDMI Video Cable', 'Earphone Wire', 'Ethernet (LAN) Cable', 'd'),
  (6, 'Basic Networking & Connectivity', 'easy', 'On a mobile phone status bar, what do "4G" and "5G" indicate?', 'How many gigabytes of storage are left', 'How many games are installed', 'Battery percentage', 'Generations of mobile cellular network connectivity for internet and calls', 'd'),
  (6, 'Basic Networking & Connectivity', 'medium', 'When you save a PDF circular FROM a school website ONTO your phone, is that called Downloading or Uploading?', 'Printing', 'Downloading', 'Uploading', 'Scanning', 'b'),
  (6, 'Basic Networking & Connectivity', 'medium', 'When you select a photo FROM your computer and post/submit it TO an online portal, is that called Downloading or Uploading?', 'Rebooting', 'Downloading', 'Uploading', 'Formatting', 'c'),
  (6, 'Basic Networking & Connectivity', 'medium', 'Look at the curved fan-shaped icon with 3 or 4 arcs in the corner of your phone or laptop screen. What does it show?', 'Wi-Fi connection and signal strength', 'Screen brightness', 'CPU temperature', 'Speaker volume level', 'a'),
  (6, 'Basic Networking & Connectivity', 'medium', 'Which of these tasks works completely OFFLINE even when you have zero internet connection?', 'Using the built-in Calculator or typing in Notepad', 'Streaming a live YouTube video', 'Sending an email', 'Searching on Google', 'a'),
  (6, 'Basic Networking & Connectivity', 'medium', 'Why do home and school Wi-Fi networks have a password?', 'Because routers cannot turn on without a 20-letter name', 'So strangers outside cannot use your internet or access devices on your network', 'To charge phones faster', 'To make the router light turn blue', 'b'),
  (6, 'Basic Networking & Connectivity', 'medium', 'When a YouTube video pauses with a spinning circle in the middle because the internet is slow, what is that called?', 'Printing', 'Zipping', 'Buffering', 'Scanning', 'c'),
  (6, 'Basic Networking & Connectivity', 'medium', 'Roughly how far does normal Bluetooth (like wireless earbuds connected to your phone) usually reach clearly?', 'Only 1 millimeter', 'Around the whole planet', 'Across the entire state (500 km)', 'A short room-size distance (around 10 meters / 30 feet)', 'd'),
  (6, 'Basic Networking & Connectivity', 'hard', 'Your laptop says "Connected to Wi-Fi, No Internet." What does this message actually mean?', 'Your laptop Wi-Fi card is broken', 'Your screen is damaged', 'You forgot your laptop password', 'Your laptop is connected to the Wi-Fi router in the room, but the router’s outside internet line is down', 'd'),
  (6, 'Basic Networking & Connectivity', 'hard', 'Why are desktop computers in an exam lab often connected by Ethernet (LAN) cables instead of Wi-Fi?', 'LAN cables also power the monitor without electricity', 'A wired Ethernet cable gives steadier, interference-free internet for 30+ PCs at the same time', 'Desktop PCs can never use Wi-Fi', 'Wi-Fi only works on phones', 'b'),
  (6, 'Basic Networking & Connectivity', 'hard', 'Internet plan speeds from providers like JioFiber, Airtel, or BSNL are commonly advertised in "100 Mbps". What does Mbps measure?', 'How far the Wi-Fi reaches in meters', 'How many months the plan lasts', 'Megabits per second — how fast data transfers over your internet connection', 'How many devices are allowed', 'c'),
  (6, 'Basic Networking & Connectivity', 'hard', 'Companies like BSNL, Airtel, Jio, or local fiber broadband providers that connect homes/schools to the internet are called:', 'ISPs (Internet Service Providers)', 'Search Engines', 'Operating Systems', 'Web Browsers', 'a'),
  (6, 'Social Ethics & Cyber Safety', 'easy', 'If a stranger calls claiming to be from a bank or school and asks for the 6-digit OTP on your phone, what should you ALWAYS do?', 'NEVER share the OTP with anyone — hang up and tell a parent or teacher', 'Send a screenshot of the OTP', 'Also share your ATM PIN', 'Read out the OTP quickly', 'a'),
  (6, 'Social Ethics & Cyber Safety', 'easy', 'Before posting a funny photo or video of your classmate on social media, what is the right social ethic to follow?', 'Always ask your classmate’s clear permission first, and respect it if they say no', 'Post it secretly without asking', 'Tag 50 strangers on it', 'Edit it to embarrass them', 'a'),
  (6, 'Social Ethics & Cyber Safety', 'easy', 'When you finish using a shared computer in the school computer lab, what should you ALWAYS do before leaving your seat?', 'Leave your email and portal logged in for the next class', 'Log out of your account and close your browser session cleanly', 'Change the desktop language', 'Unplug the keyboard wires', 'b'),
  (6, 'Social Ethics & Cyber Safety', 'easy', 'Which of these is the STRONGEST and safest password?', 'password', 'abcd1234', 'M@ples#2026!Star', '12345678', 'c'),
  (6, 'Social Ethics & Cyber Safety', 'easy', 'In online group chats or comments, typing an entire message IN ALL CAPITAL LETTERS LIKE THIS is usually read as:', 'Encrypting the message', 'Writing faster', 'Whispering politely', 'SHOUTING or being rude online', 'd'),
  (6, 'Social Ethics & Cyber Safety', 'easy', 'If a junior student asks a very basic computer question in the tech club, how should a good member respond?', 'Laugh at them in front of the group', 'Tell them to quit computers', 'Ignore them completely', 'Explain it patiently and kindly — everyone starts as a beginner!', 'd'),
  (6, 'Social Ethics & Cyber Safety', 'easy', 'If someone repeatedly sends mean, hurtful, or threatening messages to a classmate online, what is that harmful behavior called?', 'Web Browsing', 'Cyberbullying (which must be reported to parents/teachers, never joined!)', 'Cloud Computing', 'Troubleshooting', 'b'),
  (6, 'Social Ethics & Cyber Safety', 'medium', 'You receive a dramatic WhatsApp forward saying "Tomorrow is a sudden holiday — forward to 20 friends!" What is the smart, responsible step?', 'Skip homework without checking', 'Forward it to 50 groups immediately', 'Do NOT forward blindly — verify first from the official school notice or teacher', 'Post it as breaking news', 'c'),
  (6, 'Social Ethics & Cyber Safety', 'medium', 'Why shouldn’t you eat sticky snacks or keep an open cup of water right over a computer keyboard?', 'Crumbs and spilled liquid can permanently short-circuit and ruin the keyboard or laptop', 'Water changes the wallpaper', 'Snacks reduce Wi-Fi bars', 'Food slows down Google Search', 'a'),
  (6, 'Social Ethics & Cyber Safety', 'medium', 'If a pop-up flashes on screen: "🎉 CONGRATULATIONS! You won a free iPhone! Click here & enter your details!", what is it almost certainly?', 'A scam / phishing trap trying to steal personal details or install malware — close it immediately!', 'A real gift from your browser', 'An official CBSE scholarship', 'A Windows system update', 'a'),
  (6, 'Social Ethics & Cyber Safety', 'medium', 'What is "Netiquette"?', 'A brand of Ethernet cable', 'Good manners, kindness, and respectful behavior when communicating on the internet', 'An offline calculator game', 'A type of mosquito net', 'b'),
  (6, 'Social Ethics & Cyber Safety', 'medium', 'Should you share your home address, school timetable, and phone number publicly with unknown strangers in online game chats?', 'Yes, if they have a cool profile picture', 'Yes, on every public comment section', 'No — keep personal details private to stay safe online', 'Yes, if they offer free game coins', 'c'),
  (6, 'Social Ethics & Cyber Safety', 'medium', 'When you use a diagram, photo, or quote created by someone else in your school presentation, what is the honest thing to do?', 'Never use books or references', 'Forbid anyone else from seeing the source', 'Crop out their name and claim it as yours', 'Give clear credit to the original creator or source instead of pretending you made it yourself', 'd'),
  (6, 'Social Ethics & Cyber Safety', 'medium', 'To keep your eyes comfortable while studying or working on a computer, what does the healthy "20-20-20 Rule" recommend?', 'Sit 20 millimeters from the screen for 20 hours', 'Open 20 tabs at brightness 20%', 'Blink only 20 times a day', 'Every 20 minutes, look at something 20 feet away for 20 seconds to relax your eyes', 'd'),
  (6, 'Social Ethics & Cyber Safety', 'hard', 'Important UPI Safety Rule in India: Do you EVER need to enter your secret UPI PIN to RECEIVE money from someone?', 'Yes, scanning any QR code automatically credits money after PIN', 'NEVER! A UPI PIN is ONLY entered when money is GOING OUT from your account — asking you to enter PIN to "receive" money is a scam!', 'Yes, you must enter UPI PIN to receive gifts', 'UPI PIN is just your roll number', 'b'),
  (6, 'Social Ethics & Cyber Safety', 'hard', 'What is "Two-Factor Authentication (2FA)" on email or social accounts, and why is it great?', 'It deletes your account after two days', 'It forces two friends to share one account', 'It adds a second check (like a code on your phone) besides your password, so thieves can’t break in with a leaked password alone', 'It slows down typing speed by half', 'c'),
  (6, 'Social Ethics & Cyber Safety', 'hard', 'Why is reusing the EXACT SAME password across 10 different games, websites, and your main email risky?', 'If even one small game site gets hacked, attackers immediately try that same password on your email and other accounts!', 'It uses extra storage on your phone', 'There is zero risk', 'Browsers block repeated passwords', 'a'),
  (6, 'Social Ethics & Cyber Safety', 'hard', 'How should a responsible student use AI tools (like ChatGPT or Gemini) when working on a project or assignment?', 'Use AI to brainstorm, understand tough ideas, or debug — then write/build in your own understanding and honestly mention where AI helped', 'Copy-paste the entire AI output without reading a word and sign it as 100% your own', 'Trust every single date or quote from AI without checking', 'Use AI during closed-book tests', 'a');
